def find_foreign_fields(role: PartRole, fields: dict) -> list[str]:
    """Fields holding a value that `role` may not send (an empty list or dict is no value)."""
    return sorted(name for name, value in fields.items()
                  if value not in (None, [], {}) and role not in FIELD_OWNERS.get(name, (role,)))


class SamplePartIn(_SAMPLE_PART):
    """One part on the wire. The server derives the sample id from `key` and the batch's write epoch."""

    role: PartRole
    #: The step this part counts toward in that step's seal; stamped once by the producer.
    seal_step: int | None = Field(default=None, ge=0)
    #: An attempt part's beat.
    heartbeat_at: datetime | None = None
    #: An attempt part's kind (`AttemptKind`); none reads as progress (`LEGACY_ATTEMPT_KIND`).
    attempt_kind: AttemptKind | None = None
    start: AttemptStart | None = None
    progress: AttemptProgress | None = None
    end: AttemptEnd | None = None
    #: The producer key of the attempt this one replaces (Harbor `retry_of`): that one reads superseded.
    supersedes_key: str | None = Field(default=None, max_length=MAX_KEY_CHARS)

    @model_validator(mode="after")
    def _owned(self) -> SamplePartIn:
        fields = {name: getattr(self, name) for name in type(self).model_fields if name not in _ALWAYS_SENT}
        foreign = find_foreign_fields(self.role, fields)
        if foreign:
            raise ValueError(f"a {self.role} part may not send {foreign} (part.FIELD_OWNERS)")
        if self.role is PartRole.GENERATOR and self.task_key is None:
            raise ValueError("a generator part names its task_key")
        if self.role is PartRole.ATTEMPT:
            self._check_attempt()
        return self

    def _check_attempt(self) -> None:
        """An attempt part is keyed by its attempt, and sends only its own kind's block (an end always has one)."""
        if self.attempt_key is not None and self.attempt_key != self.key:
            raise ValueError("an attempt part is keyed by its attempt: attempt_key must equal key")
        for kind, name in ATTEMPT_KIND_FIELDS.items():
            if getattr(self, name) is not None and self.attempt_kind is not kind:
                raise ValueError(f"only an attempt_kind={kind} part sends `{name}`")
        if self.attempt_kind is AttemptKind.END and self.end is None:
            raise ValueError("an end part says how it ended (`end.outcome`)")
        is_canceled = self.end is not None and self.end.outcome is AttemptOutcome.CANCELED
        if is_canceled and self.error_reason not in (None, SampleErrorReason.CANCELED):
            raise ValueError("a canceled attempt's error_reason is `canceled`")

    @property
    def is_final(self) -> bool:
        """Counts toward its seal: a generator part with content, a reward, an error or a drop; a trainer part
        that consumed or dropped the sample. Attempt beats, scorer and harbor parts never do."""
        has_drop = self.drop_reason is not None
        if self.role is PartRole.GENERATOR:
            has_content = bool(self.response or self.response_blob or self.turns or self.turns_blob)
            return has_content or self.reward is not None or self.error_reason is not None or has_drop
        return self.role is PartRole.TRAINER and (self.consumed_step is not None or has_drop)
